export type Dict = typeof ar;
export const DICTS: Record<Lang, Dict> = { ar, en };
export const I18n = createContext<{ t: Dict; lang: Lang }>({ t: ar, lang: "ar" });
export const useT = () => useContext(I18n);
export const fill = (s: string, vars: Record<string, string>) => s.replace(/\{(\w+)\}/g, (_, k) => vars[k] ?? "");

export const minsText = (t: Dict, m: number) =>
  fill(m === 1 ? t.buyMinutes1 : m === 2 ? t.buyMinutes2 : m <= 10 ? t.buyMinutesFew : t.buyMinutes, { m: String(m) });

export const pwError = (t: Dict, e: unknown) => {
  const m = (e as Error)?.message;
  if (m === "ERR_IMPORTED") return t.impUnreadable;
  if (m === "ERR_RETRY") return t.impRetry;
  const w = (e as { waitMs?: number })?.waitMs;
  return w ? fill(t.pwWait, { s: String(Math.ceil(w / 1000)) }) : t.wrongPw;
};

export const gasSpeedLabel = (t: Dict, s: "slow" | "normal" | "fast") => (s === "slow" ? t.gasSlow : s === "fast" ? t.gasFast : t.gasNormal);

export const watchTexts = (t: Dict) => ({ inTitle: t.ntInTitle, inBody: t.ntInBody, okTitle: t.ntOkTitle, failTitle: t.ntFailTitle, send: t.ntSend, swap: t.ntSwap });
